function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // sky
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(200, 0);
  brush.vertex(200, 200);
  brush.vertex(400, 0);
  brush.endShape(true);
  brush.noFill();
  brush.noStroke();
  // hills
  brush.fill("#7c9b8b");
  brush.beginShape();
  brush.vertex(200, 200);
  brush.vertex(200, 250);
  brush.vertex(250, 250);
  brush.vertex(250, 200);
  brush.endShape(true);
  brush.noFill();
  brush.noStroke();
  // horizon
  brush.fill("#834326");
  brush.beginShape();
  brush.vertex(0, 400);
  brush.vertex(200, 350);
  brush.vertex(400, 400);
  brush.endShape(true);
  brush.noFill();
  brush.stroke(100);
  // details
  brush.fill("#e08a72");
  brush.beginShape();
  brush.vertex(400, 350);
  brush.vertex(300, 350);
  brush.vertex(300, 400);
  brush.endShape(true);
}
